function seededPositions(count, seedBase, spread) {
  const out = [];
  let seed = seedBase;
  for (let i = 0; i < count; i++) {
    seed = (seed * 9301 + 49297) % 233280;
    const r1 = seed / 233280;
    seed = (seed * 9301 + 49297) % 233280;
    const r2 = seed / 233280;
    out.push({ x: r1 * spread, y: r2 * 100 });
  }
  return out;
}

