class WeatherCardAussonne extends HTMLElement {
  constructor() {
    super();
    this.attachShadow({ mode: "open" });
  }

  setConfig(config) {
    if (!config || !config.entity) {
      throw new Error("Merci de définir 'entity' (ex: weather.maville)");
    }
    this._config = {
      sun_entity: "sun.sun",
      forecast_days: 4,
      forecast_hours: 5,
      show_hourly: true,
      show_details: true,
      tap_action: "more-info",
      name: null,
      ...config,
    };
    this._forecast = null;
    this._forecastHourly = null;
    this._forecastSub = null;
    this._forecastHourlySub = null;
    this._dailyReady = false;
    this._hourlyReady = false;
    this._lastRenderKey = null;
    if (!this._built) {
      this.shadowRoot.innerHTML = `<style>${CARD_CSS}</style><svg width="0" height="0" style="position:absolute;overflow:hidden"><defs>
  <radialGradient id="sun" cx="35%" cy="30%">
    <stop offset="0" stop-color="#fff7b0"/><stop offset=".45" stop-color="#ffd54a"/><stop offset="1" stop-color="#f4a900"/>
  </radialGradient>
  <radialGradient id="moon" cx="35%" cy="30%">
    <stop offset="0" stop-color="#f8fbff"/><stop offset=".55" stop-color="#d3ddef"/><stop offset="1" stop-color="#93a2c4"/>
  </radialGradient>
  <linearGradient id="cloud" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0" stop-color="#ffffff"/><stop offset=".45" stop-color="#e9eef5"/><stop offset="1" stop-color="#aeb9c8"/>
  </linearGradient>
  <linearGradient id="cloudDark" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0" stop-color="#77889d"/><stop offset=".5" stop-color="#435367"/><stop offset="1" stop-color="#1f2b3a"/>
  </linearGradient>
  <linearGradient id="rain" x1="0" y1="0" x2="1" y2="1">
    <stop offset="0" stop-color="#aee9ff"/><stop offset=".5" stop-color="#35aeea"/><stop offset="1" stop-color="#1673c4"/>
  </linearGradient>
  <linearGradient id="snow" x1="0" y1="0" x2="1" y2="1">
    <stop offset="0" stop-color="#ffffff"/><stop offset="1" stop-color="#a9c6df"/>
  </linearGradient>
  <filter id="shadow" x="-30%" y="-30%" width="160%" height="180%">
    <feDropShadow dx="0" dy="8" stdDeviation="7" flood-opacity=".25"/>
  </filter>
  <filter id="glow">
    <feGaussianBlur stdDeviation="3" result="b"/>
    <feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge>
  </filter>
  <style>
    .cloud{fill:url(#cloud);filter:url(#shadow)}
    .dark{fill:url(#cloudDark);filter:url(#shadow)}
    .sun{fill:url(#sun);filter:url(#glow)}
    .moon{fill:url(#moon);filter:url(#glow)}
    .ray{stroke:#ffd34d;stroke-width:9;stroke-linecap:round}
    .rain{stroke:url(#rain);stroke-width:8;stroke-linecap:round}
    .snow{stroke:url(#snow);stroke-width:5;stroke-linecap:round}
    .bolt{fill:#ffd52a;filter:url(#glow)}
    .animate-sun{transform-origin:50px 50px;animation:spin 18s linear infinite}
    .animate-moon{animation:float 5s ease-in-out infinite}
    .animate-cloud{animation:float 4s ease-in-out infinite}
    .animate-rain{animation:fall .8s linear infinite}
    .animate-rain2{animation:fall 1.1s linear infinite .25s}
    .animate-snow{animation:snowfall 2.4s linear infinite}
    .animate-wind{animation:drift 2.2s ease-in-out infinite}
    .animate-bolt{animation:flash 2.8s ease-in-out infinite}
    @keyframes spin{to{transform:rotate(360deg)}}
    @keyframes float{0%,100%{transform:translateY(0)}50%{transform:translateY(-4px)}}
    @keyframes fall{0%{transform:translateY(-7px);opacity:.35}50%{opacity:1}100%{transform:translateY(10px);opacity:.35}}
    @keyframes snowfall{0%{transform:translateY(-5px) rotate(0);opacity:.35}50%{opacity:1}100%{transform:translateY(12px) rotate(25deg);opacity:.35}}
    @keyframes drift{0%,100%{transform:translateX(-4px)}50%{transform:translateX(5px)}}
    @keyframes flash{0%,82%,100%{opacity:.55}86%,90%{opacity:1}88%{opacity:.25}}
  </style>
</defs></svg><ha-card><div class="wca-root"></div></ha-card>`;
      this._built = true;
      const card = this.shadowRoot.querySelector("ha-card");
      card.style.cursor = "pointer";
      card.addEventListener("click", () => this._handleTap());
    }
  }

  _handleTap() {
    if (this._config.tap_action === "none") return;
    this.dispatchEvent(new CustomEvent("hass-more-info", {
      bubbles: true,
      composed: true,
      detail: { entityId: this._config.entity },
    }));
  }

  static getStubConfig() {
    return { entity: "weather.home", sun_entity: "sun.sun" };
  }

  static getConfigElement() {
    return document.createElement("weather-card-aussonne-editor");
  }

  set hass(hass) {
    this._hass = hass;
    const stateObj = hass.states[this._config.entity];
    if (!stateObj) {
      this._renderError(`Entité introuvable : ${this._config.entity}`);
      return;
    }
    if (!this._subscribedFor || this._subscribedFor !== this._config.entity) {
      this._subscribedFor = this._config.entity;
      this._subscribeForecast();
    }
    this._render();
  }

  async _subscribeForecast() {
    this._unsub(this._forecastSub);
    this._forecastSub = null;
    this._unsub(this._forecastHourlySub);
    this._forecastHourlySub = null;
    this._dailyReady = false;
    this._hourlyReady = !this._config.show_hourly;

    try {
      this._forecastSub = await this._hass.connection.subscribeMessage(
        (msg) => {
          this._forecast = (msg && msg.forecast) || [];
          this._dailyReady = true;
          this._render();
        },
        { type: "weather/subscribe_forecast", entity_id: this._config.entity, forecast_type: "daily" }
      );
    } catch (e) {
      const stateObj = this._hass.states[this._config.entity];
      this._forecast = (stateObj && stateObj.attributes && stateObj.attributes.forecast) || [];
      this._dailyReady = true;
    }

    if (this._config.show_hourly) {
      try {
        this._forecastHourlySub = await this._hass.connection.subscribeMessage(
          (msg) => {
            this._forecastHourly = (msg && msg.forecast) || [];
            this._hourlyReady = true;
            this._render();
          },
          { type: "weather/subscribe_forecast", entity_id: this._config.entity, forecast_type: "hourly" }
        );
      } catch (e) {
        this._forecastHourly = [];
        this._hourlyReady = true;
      }
    } else {
      this._forecastHourly = [];
    }

    this._render();
  }

  _unsub(fn) {
    if (fn) {
      try { fn(); } catch (e) {}
    }
  }

  disconnectedCallback() {
    this._unsub(this._forecastSub);
    this._forecastSub = null;
    this._unsub(this._forecastHourlySub);
    this._forecastHourlySub = null;
  }

  _renderError(msg) {
    const root = this.shadowRoot.querySelector(".wca-root");
    if (root) root.innerHTML = `<div class="wca-error">${msg}</div>`;
  }

  _render() {
    const hass = this._hass;
    const cfg = this._config;
    const stateObj = hass.states[cfg.entity];
    if (!stateObj) return;

    const condition = stateObj.state in DAY_BG ? stateObj.state : "cloudy";
    const sunState = hass.states[cfg.sun_entity];
    const isDay = sunState ? sunState.state === "above_horizon" : condition !== "clear-night";

    const forecastReady = this._dailyReady && this._hourlyReady;
    const renderKey = JSON.stringify({ condition, isDay, t: stateObj.attributes.temperature, f: this._forecast, fh: this._forecastHourly, ready: forecastReady });
    if (renderKey === this._lastRenderKey) return;
    this._lastRenderKey = renderKey;

    const bg = (isDay ? DAY_BG : NIGHT_BG)[condition] || DAY_BG.cloudy;
    const name = cfg.name || stateObj.attributes.friendly_name || "Météo";
    const temp = stateObj.attributes.temperature;
    const unit = hass.config?.unit_system?.temperature || "°C";
    const label = CONDITION_LABEL_FR[condition] || condition;
    const humidity = stateObj.attributes.humidity;
    const windSpeed = stateObj.attributes.wind_speed;
    const windUnit = stateObj.attributes.wind_speed_unit || hass.config?.unit_system?.wind_speed || "km/h";

    const forecast = (this._forecast || []).slice(0, cfg.forecast_days);
    const today = forecast[0];
    const hi = today && today.temperature != null ? Math.round(today.temperature) : null;
    const lo = today && today.templow != null ? Math.round(today.templow) : null;

    const dateStr = new Intl.DateTimeFormat("fr-FR", { weekday: "long", day: "numeric", month: "long" }).format(new Date());

    const particlesOverlay = this._backgroundParticles(condition, isDay);

    const forecastHtml = forecast.map((f) => {
      const c = f.condition in DAY_BG ? f.condition : "cloudy";
      const h = f.temperature != null ? Math.round(f.temperature) : "–";
      const l = f.templow != null ? Math.round(f.templow) : "–";
      return `
        <div class="wca-fday">
          <div class="wca-fday-temp">${h}/${l}°</div>
          <div class="wca-fday-icon">${iconSvg(c, true, { size: 40 })}</div>
          <div class="wca-fday-name">${fmtDay(f.datetime)}</div>
        </div>`;
    }).join("");

    const hourly = cfg.show_hourly ? (this._forecastHourly || []).slice(0, cfg.forecast_hours) : [];
    const hourlyHtml = hourly.map((f) => {
      const c = f.condition in DAY_BG ? f.condition : "cloudy";
      const t = f.temperature != null ? Math.round(f.temperature) : "–";
      return `
        <div class="wca-hitem">
          <div class="wca-hitem-temp">${t}°</div>
          <div class="wca-hitem-icon">${iconSvg(c, true, { size: 28 })}</div>
          <div class="wca-hitem-hour">${fmtHour(f.datetime)}</div>
        </div>`;
    }).join("");

    const root = this.shadowRoot.querySelector(".wca-root");
    root.innerHTML = `
      <div class="wca-bg" style="background:${bg}">
        ${particlesOverlay}
        <div class="wca-mountains" style="background-image:url('${MOUNTAIN_IMG}');filter:${isDay ? "none" : "brightness(.5) saturate(.7)"}"></div>
      </div>
      <div class="wca-content">
        <div class="wca-header">
          <div class="wca-header-temp">
            <div class="wca-temp">${temp != null ? Math.round(temp) : "–"}<span class="wca-unit">${unit}</span></div>
            <div class="wca-cond">${label}</div>
          </div>
          <div class="wca-header-name">
            <div class="wca-name">${name}</div>
            <div class="wca-date">${dateStr}</div>
          </div>
        </div>
        <div class="wca-main">
          <div class="wca-temp-block">
            ${hi != null || lo != null ? `
              <div class="wca-hilo">
                ${hi != null ? `<span class="hi">▲ ${hi}°</span>` : ""}
                ${lo != null ? `<span class="lo">▼ ${lo}°</span>` : ""}
              </div>` : ""}
            ${cfg.show_details && (humidity != null || windSpeed != null) ? `
              <div class="wca-details">
                ${humidity != null ? `<span class="detail">${DROPLET_ICON}${Math.round(humidity)}%</span>` : ""}
                ${windSpeed != null ? `<span class="detail">${WIND_ICON}${Math.round(windSpeed)} ${windUnit}</span>` : ""}
              </div>` : ""}
          </div>
          <div class="wca-icon-big">${iconSvg(condition, isDay, { size: 108 })}</div>
        </div>
      </div>
      ${!forecastReady ? `
      <div class="wca-bottom">
        <div class="wca-skeleton">
          <div class="wca-skeleton-bar" style="width:60%"></div>
          <div class="wca-skeleton-bar" style="width:85%"></div>
        </div>
      </div>` : (forecast.length || hourly.length ? `
      <div class="wca-bottom">
        ${forecast.length ? `<div class="wca-forecast">${forecastHtml}</div>` : ""}
        ${hourly.length ? `<div class="wca-hourly">${hourlyHtml}</div>` : ""}
      </div>` : "")}
    `;
  }

  _backgroundParticles(condition, isDay) {
    if (!isDay && (condition === "clear-night" || condition === "partlycloudy" || condition === "cloudy")) {
      return `<div class="wca-stars">${STARS.map((s, i) => `<div class="star" style="left:${s.x.toFixed(1)}%;top:${(s.y * 0.55).toFixed(1)}%;animation-delay:${(i % 6 * 0.4).toFixed(1)}s"></div>`).join("")}</div>`;
    }
    if (RAIN_FAMILY.includes(condition)) {
      const n = condition === "pouring" ? 40 : 22;
      const drops = seededPositions(n, 7, 100);
      return `<div class="wca-rainbg">${drops.map((d, i) => `<div class="rainline" style="left:${d.x.toFixed(1)}%;animation-delay:${(i % 10 * 0.11).toFixed(2)}s;animation-duration:${(0.5 + (i % 5) * 0.08).toFixed(2)}s"></div>`).join("")}</div>`;
    }
    if (SNOW_FAMILY.includes(condition)) {
      const n = 26;
      const flakes = seededPositions(n, 13, 100);
      return `<div class="wca-snowbg">${flakes.map((f, i) => `<div class="snowdot" style="left:${f.x.toFixed(1)}%;animation-delay:${(i % 8 * 0.5).toFixed(1)}s;animation-duration:${(4 + (i % 5)).toFixed(1)}s"></div>`).join("")}</div>`;
    }
    if (condition === "fog") {
      return `<div class="wca-fogbg"><div class="fogband" style="top:30%"></div><div class="fogband" style="top:55%;animation-delay:-4s"></div><div class="fogband" style="top:78%;animation-delay:-8s"></div></div>`;
    }
    return "";
  }

  getCardSize() {
    return 6;
  }
}

const EDITOR_SCHEMA = [
  { name: "entity", required: true, selector: { entity: { domain: "weather" } } },
  { name: "sun_entity", selector: { entity: { domain: "sun" } } },
  { name: "name", selector: { text: {} } },
  { name: "forecast_days", selector: { number: { min: 0, max: 10, mode: "box" } } },
  { name: "forecast_hours", selector: { number: { min: 0, max: 24, mode: "box" } } },
  { name: "show_hourly", selector: { boolean: {} } },
  { name: "show_details", selector: { boolean: {} } },
  { name: "tap_action", selector: { select: { options: [
    { value: "more-info", label: "Plus d'infos" },
    { value: "none", label: "Aucune action" },
  ] } } },
];

const EDITOR_LABELS = {
  entity: "Entité météo",
  sun_entity: "Entité soleil",
  name: "Titre (optionnel)",
  forecast_days: "Jours de prévisions",
  forecast_hours: "Heures de prévisions",
  show_hourly: "Afficher les prévisions horaires",
  show_details: "Afficher humidité / vent",
  tap_action: "Action au clic",
};

class WeatherCardAussonneEditor extends HTMLElement {
  setConfig(config) {
    this._config = config;
    this._render();
  }

  set hass(hass) {
    this._hass = hass;
    this._render();
  }

  _render() {
    if (!this._hass || !this._config) return;
    if (!this._form) {
      this._form = document.createElement("ha-form");
      this._form.addEventListener("value-changed", (ev) => {
        this._config = ev.detail.value;
        this.dispatchEvent(new CustomEvent("config-changed", { detail: { config: this._config } }));
      });
      this.appendChild(this._form);
    }
    this._form.hass = this._hass;
    this._form.data = this._config;
    this._form.schema = EDITOR_SCHEMA;
    this._form.computeLabel = (s) => EDITOR_LABELS[s.name] || s.name;
  }
}

customElements.define("weather-card-aussonne-editor", WeatherCardAussonneEditor);
customElements.define("weather-card-aussonne", WeatherCardAussonne);

window.customCards = window.customCards || [];
window.customCards.push({
  type: "weather-card-aussonne",
  name: "Carte Météo Aussonne",
  description: "Carte météo avec arrière-plan dynamique selon la météo actuelle",
});
